SELECT ?pt ?lbl ?cls WHERE {
  ?pt a ?cls .
  ?pt <http://www.w3.org/2000/01/rdf-schema#label> ?lbl .
  FILTER(CONTAINS(LCASE(str(?cls)), "occupan") || CONTAINS(LCASE(str(?cls)), "person"))
} LIMIT 200

SELECT DISTINCT ?cls WHERE {
  ?s a ?cls .
  FILTER(CONTAINS(LCASE(str(?cls)), "occupan") || CONTAINS(LCASE(str(?cls)), "person") || CONTAINS(LCASE(str(?cls)), "presence"))
}

SELECT ?pt ?lbl ?tsid WHERE {
  ?pt a brick:Occupancy_Sensor .
  OPTIONAL { ?pt <http://www.w3.org/2000/01/rdf-schema#label> ?lbl . }
  OPTIONAL { ?pt ref:hasTimeseriesId ?tsid . }
